package com.deliverysaas.drivers;
import java.util.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.deliverysaas.shared.security.AuthPrincipal;import jakarta.validation.Valid;
@RestController @RequestMapping("/api/v1/drivers") public class DriverLocationController{private final DriverLocationService service;public DriverLocationController(DriverLocationService s){service=s;}@PostMapping("/me/locations")public ResponseEntity<DriverLocationResponse> create(@AuthenticationPrincipal AuthPrincipal p,@Valid @RequestBody CreateDriverLocationRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(p,r));}@GetMapping("/{id}/locations")public List<DriverLocationResponse> all(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){return service.all(p,id);}@GetMapping("/{id}/locations/latest")public DriverLocationResponse latest(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){return service.latest(p,id);}}
